/**
 * Apply changesets to a lexicon: how 1.2 is built from 1.1 (ADR-0013).
 *
 * Pure: the caller reads the baseline, the changesets and the id sidecar, and
 * writes what comes back. Every operation checks that it lands on what it
 * says it replaces, so a changeset written against another baseline fails
 * loudly instead of applying half-right.
 *
 * What the build adds beyond the ops themselves:
 * - every record carries an inline `id` (ADR-0008); 1.0 ids come from the
 *   sidecar, 1.1 additions are minted in lexicon order, then 1.2 additions;
 * - forms are generated by the verb rule, never copied (ADR-0009 §3);
 * - `rhyme_families` is rebuilt from every headword, as build_1_0.py built it.
 */
import { FORM_SLOTS, SLOT_RAW_KEY, isUnusedGloss, type FormSlot } from '../config/slots';
import { senses } from '../integrate/synonyms';
import { IdAssigner, type IdKind, type IdMapFile } from '../model/ids';
import type { RawLexicon, RawSlots } from '../model/raw';
import { sevenForms } from '../morphology/sevenForms';
import { type ChangeRecord, type Changeset, validateChangeset } from './changelog';
import { respellAsCompoundInPlace, respellRootInPlace, retireRootInPlace } from './respell';

export interface ChangesetRuling {
  id: string;
  topic: string;
  ruling: string;
  refines?: string[];
  examples?: [string, string][];
}

export interface NewHeadword {
  id: string;
  root: string;
  type: 'Primal' | 'Compound';
  components: [string, string] | null;
  /**
   * A compound lexicalised with a suffix (2.0:G38): the spelling is the
   * components joined, then this suffix (`viofuroti` = vio + furo + -ti).
   */
  suffix?: string;
  glosses: RawSlots;
  register: string;
  domain: string;
  english_synonyms: string[];
  notes: string;
}

type Row = Record<string, unknown> & { id?: string };

/** A changeset with the payloads its add_* ops point at. */
export interface LexiconChangeset extends Changeset {
  rulings?: ChangesetRuling[];
  headwords?: NewHeadword[];
  function_words?: (Row & { id: string; form: string })[];
  correlatives?: (Row & { id: string; form: string })[];
  lexicalised_derivations?: Record<string, string>;
  motion_metaphors?: Record<string, string>;
  /** New data sections by path, for `add_section` (ADR-0016). */
  sections?: Record<string, unknown>;
}

/**
 * What an edition's word-building rulings allow that earlier editions did not.
 * The integration script sets these from the rulings it applies (ADR-0016),
 * so a 1.2 rebuild stays exactly as strict as it was.
 */
export interface WordBuilding {
  /** A compound may take a compound as one of its two parts (2.0:G42). */
  nesting: boolean;
  /** A colour base (the colour table's "Base color") may be a compound's modifier (2.0:G38). */
  colourModifiers: boolean;
}

export const STRICT_WORD_BUILDING: WordBuilding = { nesting: false, colourModifiers: false };

export interface ApplyOptions {
  version: string;
  builtUtc: string;
  source: string;
  ids: IdMapFile;
  /** Defaults to the strict 1.2 rules. */
  wordBuilding?: WordBuilding;
}

export interface AppliedOp {
  changeset: string;
  op: string;
  entry: string;
  to: string | null;
}

export interface ApplyResult {
  lexicon: RawLexicon;
  applied: AppliedOp[];
}

export class ApplyError extends Error {}

const UNUSED = '— (unused)';
const RAW_KEYS = FORM_SLOTS.map((s) => SLOT_RAW_KEY[s]);

interface Headword extends Row {
  root: string;
  type: string;
  components: [string, string] | null;
  suffix?: string;
  forms: Record<string, string>;
  glosses: Record<string, string>;
  english_synonyms: string[];
}

/** The natural key each section is minted under, as importLexicon does it. */
function assignSectionIds(lex: RawLexicon, assigner: IdAssigner): void {
  const section = (rows: readonly Row[], kind: IdKind, key: (r: Row) => string): void => {
    for (const r of rows) r.id = assigner.assign(kind, key(r), r.id);
  };
  section(lex.headwords as unknown as Row[], 'headword', (r) => String(r.root));
  section(lex.function_words as unknown as Row[], 'functionWord', (r) => String(r.form));
  section(lex.pronouns as unknown as Row[], 'pronoun', (r) => String(r.form));
  section(lex.correlatives as unknown as Row[], 'correlative', (r) => String(r.form));
  const seen = new Set<string>();
  section(lex.time_and_dates as unknown as Row[], 'timeWord', (r) => {
    const form = String(r.form);
    const key = seen.has(form) ? `${form}#${String(r.english)}` : form;
    seen.add(form);
    return key;
  });
  section(lex.colors as unknown as Row[], 'color', (r) => String(r['Base color']));
  section(lex.discourse_particles as unknown as Row[], 'discourseParticle', (r) => String(r.form));
}

function rawForms(root: string): Record<string, string> {
  const forms = sevenForms(root);
  return Object.fromEntries(FORM_SLOTS.map((s) => [SLOT_RAW_KEY[s], forms[s]]));
}

/**
 * Synonyms after one slot's gloss changes: drop the old gloss's senses unless
 * another slot still carries them, then add the new gloss's senses.
 */
function reglossSynonyms(h: Headword, rawKey: string, from: string, to: string): string[] {
  const elsewhere = new Set(
    RAW_KEYS.filter((k) => k !== rawKey)
      .map((k) => h.glosses[k] ?? UNUSED)
      .filter((g) => !isUnusedGloss(g))
      .flatMap((g) => senses(g).map((s) => s.toLowerCase())),
  );
  const drop = new Set(isUnusedGloss(from) ? [] : senses(from).map((s) => s.toLowerCase()));
  const kept = h.english_synonyms.filter((s) => {
    const k = s.toLowerCase();
    return !drop.has(k) || elsewhere.has(k);
  });
  const seen = new Set(kept.map((s) => s.toLowerCase()));
  for (const s of senses(to)) {
    if (!seen.has(s.toLowerCase())) {
      kept.push(s);
      seen.add(s.toLowerCase());
    }
  }
  return kept;
}

/**
 * Record on the entry that this edition changed its glosses, as
 * `status_<edition>: "REGLOSSED"` just before `since`. validate.py's check 12
 * reads `status_1_0` only, so this is what lets a later edition's regloss be
 * told from an unrecorded edit (scripts/validate_1_2.py).
 */
function markEdited(h: Headword, version: string): void {
  const key = `status_${version.replace('.', '_')}`;
  if (h[key] !== undefined) return;
  const entries = Object.entries(h);
  for (const [k] of entries) Reflect.deleteProperty(h, k);
  for (const [k, v] of entries) {
    if (k === 'since') h[key] = 'REGLOSSED';
    h[k] = v;
  }
}

/** build_1_0.py: every headword joins the family of its last four letters. */
export function rhymeFamilies(roots: readonly string[]): RawLexicon['rhyme_families'] {
  const families = new Map<string, string[]>();
  for (const w of roots) {
    const ending = w.slice(-4);
    const list = families.get(ending) ?? [];
    list.push(w);
    families.set(ending, list);
  }
  const byCodePoint = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);
  return [...families.keys()].sort(byCodePoint).map((ending) => {
    const members = (families.get(ending) ?? []).slice().sort(byCodePoint);
    return { ending, members, count: members.length };
  });
}

/** Rebuild the top level in the baseline's key order, inserting new keys after `after`. */
function withKeys(lex: RawLexicon, inserts: readonly [string, string, unknown][]): RawLexicon {
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(lex)) {
    if (inserts.some(([k]) => k === key)) continue;
    out[key] = value;
    for (const [k, after, v] of inserts) if (after === key) out[k] = v;
  }
  for (const [k, after, v] of inserts) if (!(k in out) && !(after in out)) out[k] = v;
  return out as RawLexicon;
}

/** Where each new top-level section goes, after which baseline key. */
const SECTION_AFTER: Readonly<Record<string, string>> = {
  image_compounds: 'morphology',
  reserved_root_bank: 'sound_ledger',
};

/** The colour bases a compound's modifier may be (2.0:G38). */
const colourBases = (lex: RawLexicon): Set<string> =>
  new Set(
    (lex.colors as unknown as Row[])
      .map((c) => c['Base color'])
      .filter((b): b is string => typeof b === 'string'),
  );

export function applyChangesets(
  baseline: RawLexicon,
  changesets: readonly LexiconChangeset[],
  options: ApplyOptions,
): ApplyResult {
  const rules = options.wordBuilding ?? STRICT_WORD_BUILDING;
  const lex = JSON.parse(JSON.stringify(baseline)) as RawLexicon;
  const sectionInserts: [string, string, unknown][] = [];
  const bases = colourBases(lex);
  const assigner = new IdAssigner(options.ids);
  assignSectionIds(lex, assigner);

  const heads = lex.headwords as unknown as Headword[];
  const byId = new Map<string, Headword>(heads.map((h) => [String(h.id), h]));
  const byRoot = new Map<string, Headword>(heads.map((h) => [h.root, h]));
  const rulingsByEdition = new Map<string, ChangesetRuling[]>();
  const applied: AppliedOp[] = [];
  const archived = (lex.legacy as unknown as { archived_senses: Row[] }).archived_senses;

  const headword = (op: ChangeRecord): Headword => {
    const h = byId.get(op.entry);
    if (h === undefined) throw new ApplyError(`${op.entry}: no headword has this id`);
    return h;
  };
  /**
   * `derivation:<headword id>:-<suffix>`, or `derivation:lexicalised:<spelling>:-<suffix>`
   * for a derivation built on a lexicalised derivation (lavbupago + -ti).
   */
  const derivationBase = (entry: string): { spelling: string; suffix: string } | null => {
    const m = /^derivation:(?:lexicalised:([a-z]+)|(.+)):-([a-z]+)$/.exec(entry);
    if (m === null) return null;
    const suffix = m[3] ?? '';
    if (m[1] !== undefined) {
      return m[1] in lex.morphology.lexicalised_derivations ? { spelling: m[1], suffix } : null;
    }
    const base = byId.get(m[2] ?? '');
    return base === undefined ? null : { spelling: base.root, suffix };
  };
  const mint = (kind: IdKind, key: string, claimed: string, entry: string): void => {
    const id = assigner.assign(kind, key);
    if (id !== claimed) {
      throw new ApplyError(
        `${entry}: the changeset names id ${claimed}, but the build mints ${id}`,
      );
    }
  };

  for (const cs of changesets) {
    validateChangeset(cs);
    const payload = <T extends { id: string }>(
      list: readonly T[] | undefined,
      op: ChangeRecord,
    ): T => {
      const found = list?.find((x) => x.id === op.entry);
      if (found === undefined) throw new ApplyError(`${op.entry}: ${cs.id} has no payload for it`);
      return found;
    };

    for (const op of cs.ops) {
      switch (op.op) {
        case 'add_ruling': {
          const [edition, id] = op.entry.split(':');
          const r = cs.rulings?.find((x) => x.id === id);
          if (edition === undefined || r === undefined) {
            throw new ApplyError(`${op.entry}: no such ruling in ${cs.id}`);
          }
          const list = rulingsByEdition.get(edition) ?? [];
          if (list.some((x) => x.id === id)) throw new ApplyError(`${op.entry}: added twice`);
          list.push(r);
          rulingsByEdition.set(edition, list);
          break;
        }
        case 'edit_example': {
          // `field: 'english'` edits the English line; otherwise the Liraasa
          const i = Number(op.entry.replace('example:', ''));
          const ex = lex.examples[i] as unknown as Record<string, unknown> | undefined;
          const field = op.field === 'english' ? 'english' : 'liraasa';
          if (ex === undefined || ex[field] !== op.from || op.to === null) {
            throw new ApplyError(`${op.entry}: expected "${String(op.from)}"`);
          }
          ex[field] = op.to;
          break;
        }
        case 'add_root':
        case 'add_compound': {
          const p = payload(cs.headwords, op);
          if (p.root !== op.to) throw new ApplyError(`${op.entry}: payload spells ${p.root}`);
          if (byRoot.has(p.root)) throw new ApplyError(`${p.root}: already a headword`);
          const compound = op.op === 'add_compound';
          if (compound !== (p.type === 'Compound')) {
            throw new ApplyError(`${p.root}: ${op.op} with type ${p.type}`);
          }
          if (compound) {
            const parts = p.components;
            if (parts === null || parts.join('') + (p.suffix ?? '') !== p.root) {
              throw new ApplyError(`${p.root}: spelling is not its components joined`);
            }
            if (p.suffix !== undefined && !rules.colourModifiers) {
              throw new ApplyError(`${p.root}: a compound lexicalised with a suffix needs 2.0:G38`);
            }
            parts.forEach((c, i) => {
              const part = byRoot.get(c);
              if (part === undefined) {
                // only the modifier may be a colour base, and only under 2.0:G38
                if (i === 0 && rules.colourModifiers && bases.has(c)) return;
                throw new ApplyError(`${p.root}: component ${c} is not a headword`);
              }
              if (part.type === 'Compound' && !rules.nesting)
                throw new ApplyError(`${p.root}: component ${c} would nest`);
            });
          } else if (p.components !== null) {
            throw new ApplyError(`${p.root}: a primal root has no components`);
          }
          mint('headword', p.root, p.id, op.entry);
          const glosses = Object.fromEntries(
            RAW_KEYS.map((k) => [k, (p.glosses as unknown as Record<string, string>)[k] ?? UNUSED]),
          );
          const h: Headword = {
            root: p.root,
            type: p.type,
            components: p.components,
            ...(p.suffix !== undefined ? { suffix: p.suffix } : {}),
            forms: rawForms(p.root),
            glosses,
            register: p.register,
            domain: p.domain,
            english_synonyms: p.english_synonyms,
            status_1_0: 'NEW',
            [`status_${options.version.replace('.', '_')}`]: 'NEW',
            since: options.version,
            history_0_8: null,
            notes: p.notes,
            protected: true,
            id: p.id,
          };
          heads.push(h);
          byId.set(p.id, h);
          byRoot.set(p.root, h);
          break;
        }
        case 'add_function_word': {
          const p = payload(cs.function_words, op);
          if (lex.function_words.some((f) => f.form === p.form)) {
            throw new ApplyError(`${p.form}: already a function word`);
          }
          mint('functionWord', p.form, p.id, op.entry);
          (lex.function_words as unknown as Row[]).push({ ...p });
          break;
        }
        case 'add_correlative': {
          const p = payload(cs.correlatives, op);
          mint('correlative', p.form, p.id, op.entry);
          (lex.correlatives as unknown as Row[]).push({ ...p });
          break;
        }
        case 'add_derivation': {
          const word = op.to ?? '';
          const base = derivationBase(op.entry);
          const gloss = cs.lexicalised_derivations?.[word];
          if (base === null || base.spelling + base.suffix !== word) {
            throw new ApplyError(`${op.entry}: does not build ${word}`);
          }
          if (gloss === undefined) throw new ApplyError(`${word}: no gloss in ${cs.id}`);
          const table = lex.morphology.lexicalised_derivations;
          if (word in table) throw new ApplyError(`${word}: already lexicalised`);
          table[word] = gloss;
          break;
        }
        case 'edit_derivation': {
          const base = derivationBase(op.entry);
          const table = lex.morphology.lexicalised_derivations;
          const word = base === null ? '' : base.spelling + base.suffix;
          if (base === null || table[word] !== op.from || op.to === null) {
            throw new ApplyError(`${op.entry}: expected "${String(op.from)}"`);
          }
          table[word] = op.to;
          break;
        }
        case 'edit_particle_example': {
          const m = /^particle:(.+):(\d+)$/.exec(op.entry);
          const dp = (lex.discourse_particles as unknown as (Row & { examples: Row[] })[]).find(
            (d) => d.id === m?.[1],
          );
          const ex = dp?.examples[Number(m?.[2])];
          const field = op.field === 'english' ? 'english' : 'liraasa';
          if (ex === undefined || ex[field] !== op.from || op.to === null) {
            throw new ApplyError(`${op.entry}: expected "${String(op.from)}"`);
          }
          ex[field] = op.to;
          break;
        }
        case 'add_section': {
          const value = cs.sections?.[op.entry];
          if (value === undefined) throw new ApplyError(`${op.entry}: no section in ${cs.id}`);
          const [top, inner] = op.entry.split('.');
          if (inner !== undefined) {
            const parent = (lex as unknown as Record<string, Record<string, unknown>>)[top ?? ''];
            if (parent === undefined || inner in parent)
              throw new ApplyError(`${op.entry}: cannot add here`);
            parent[inner] = JSON.parse(JSON.stringify(value)) as unknown;
          } else {
            const after = SECTION_AFTER[op.entry];
            if (after === undefined || op.entry in lex)
              throw new ApplyError(`${op.entry}: cannot add a top-level section here`);
            const copy = JSON.parse(JSON.stringify(value)) as unknown;
            (lex as unknown as Record<string, unknown>)[op.entry] = copy;
            sectionInserts.push([op.entry, after, copy]);
          }
          break;
        }
        case 'move_to_pattern': {
          const h = headword(op);
          const pattern = (
            lex as unknown as {
              image_compounds?: {
                attested: Row[];
                modifiers: Record<string, unknown>;
                heads: Record<string, unknown>;
              };
            }
          ).image_compounds;
          if (pattern === undefined) throw new ApplyError(`${op.entry}: add image_compounds first`);
          const [mod, head] = h.components ?? [];
          const modId = byRoot.get(mod ?? '')?.id;
          const headId = byRoot.get(head ?? '')?.id;
          if (
            h.type !== 'Compound' ||
            modId === undefined ||
            headId === undefined ||
            !(String(modId) in pattern.modifiers) ||
            !(String(headId) in pattern.heads)
          ) {
            throw new ApplyError(`${op.entry}: ${h.root} is not a modifier + head of the pattern`);
          }
          const users = heads.filter((x) => x.components?.includes(h.root));
          if (users.length > 0) {
            throw new ApplyError(`${op.entry}: ${users.map((u) => u.root).join(', ')} build on it`);
          }
          heads.splice(heads.indexOf(h), 1);
          byId.delete(String(h.id));
          byRoot.delete(h.root);
          pattern.attested.push(h);
          break;
        }
        case 'edit_ledger': {
          const spelling = op.entry.replace(/^ledger:/, '');
          const row = (lex.sound_ledger as unknown as Row[]).find((r) => r.spelling === spelling);
          if (row === undefined || row.state !== op.from || op.to === null) {
            throw new ApplyError(`${op.entry}: expected state ${String(op.from)}`);
          }
          row.state = op.to;
          row.reused_in = options.version;
          break;
        }
        case 'add_motion_metaphor': {
          const m = /^motion:([a-z]+-):(.+)$/.exec(op.entry);
          const verbOf = m === null ? undefined : byId.get(m[2] ?? '');
          const prefix = m?.[1] ?? '';
          const form = op.to ?? '';
          const canon = lex.motion_prefixes.canon;
          if (
            verbOf === undefined ||
            form !== prefix + (verbOf.forms.verb ?? '') ||
            !(prefix in canon)
          ) {
            throw new ApplyError(`${op.entry}: does not build ${form}`);
          }
          const text = canon[prefix] ?? '';
          const listed = /\(curated metaphors?: ([^)]*)\)/.exec(text);
          canon[prefix] =
            listed === null
              ? `${text} (curated metaphor: ${form})`
              : text.replace(listed[0], `(curated metaphors: ${listed[1] ?? ''}, ${form})`);
          break;
        }
        case 'edit_gloss':
        case 'activate_slot': {
          const h = headword(op);
          const rawKey = SLOT_RAW_KEY[op.slot as FormSlot] as string | undefined;
          if (rawKey === undefined) throw new ApplyError(`${op.entry}: slot ${String(op.slot)}`);
          const current = h.glosses[rawKey] ?? UNUSED;
          if (current !== op.from || op.to === null) {
            throw new ApplyError(
              `${op.entry} ${rawKey}: expected "${String(op.from)}", found "${current}"`,
            );
          }
          if (op.op === 'activate_slot' && !isUnusedGloss(current)) {
            throw new ApplyError(`${op.entry} ${rawKey}: activate_slot on a used slot`);
          }
          if (op.op === 'edit_gloss' && isUnusedGloss(current)) {
            throw new ApplyError(`${op.entry} ${rawKey}: edit_gloss on an unused slot`);
          }
          h.english_synonyms = reglossSynonyms(h, rawKey, current, op.to);
          h.glosses[rawKey] = op.to;
          markEdited(h, options.version);
          if (op.archive === true) {
            archived.push({
              word: h.forms[rawKey] ?? '',
              gloss_1_1: current,
              archived_in: options.version,
              replaced_by: op.to,
              note: op.reason,
            });
          }
          break;
        }
        case 'edit_metadata': {
          if (op.field === 'english_synonyms') {
            const h = headword(op);
            const from = op.from === null ? null : (JSON.parse(op.from) as unknown);
            if (JSON.stringify(h.english_synonyms) !== JSON.stringify(from) || op.to === null) {
              throw new ApplyError(`${op.entry}: synonyms are not ${String(op.from)}`);
            }
            h.english_synonyms = JSON.parse(op.to) as string[];
          } else if (op.entry === 'phonology.declared_distance_1_pairs') {
            const pairs = lex.phonology.declared_distance_1_pairs as string[][];
            const pair = op.to === null ? null : (JSON.parse(op.to) as string[]);
            if (op.from !== null || pair?.length !== 2) {
              throw new ApplyError(`${op.entry}: adds one pair, from null`);
            }
            if (pairs.some((x) => x.join() === pair.join()))
              throw new ApplyError(`${op.entry}: ${pair.join('/')} is already declared`);
            pairs.push(pair);
          } else if (op.entry === 'phonology.protected_exceptions') {
            const list = lex.phonology.protected_exceptions;
            const i = list.indexOf(op.from ?? '');
            if (i < 0 || op.to === null)
              throw new ApplyError(`${op.entry}: "${String(op.from)}" not found`);
            list[i] = op.to;
          } else {
            throw new ApplyError(
              `${op.entry}: edit_metadata of ${String(op.field)} is not supported`,
            );
          }
          break;
        }
        case 'respell_root':
        case 'respell_as_compound':
        case 'retire_and_replace': {
          // the same code the editor's rename tool runs (respell.ts)
          if (op.to === null) throw new ApplyError(`${op.entry}: ${op.op} needs a "to"`);
          const h = headword(op);
          if (op.from !== null && h.root !== op.from) {
            throw new ApplyError(`${op.entry}: expected ${op.from}, found ${h.root}`);
          }
          try {
            if (op.op === 'respell_root') respellRootInPlace(lex, op.entry, op.to, op.reason);
            else if (op.op === 'respell_as_compound') {
              const parts = op.to.split('+');
              if (parts.length !== 2 || parts.some((x) => x === ''))
                throw new ApplyError(`${op.entry}: "to" must be MODIFIER+HEAD`);
              if (!rules.nesting && parts.some((x) => byRoot.get(x)?.type === 'Compound'))
                throw new ApplyError(`${op.entry}: ${op.to} would nest`);
              respellAsCompoundInPlace(lex, op.entry, parts as [string, string], op.reason);
            } else retireRootInPlace(lex, op.entry, op.to, op.reason);
          } catch (e) {
            if (e instanceof ApplyError) throw e;
            throw new ApplyError(`${op.entry}: ${(e as Error).message}`);
          }
          byId.clear();
          byRoot.clear();
          for (const h of heads) {
            byId.set(String(h.id), h);
            byRoot.set(h.root, h);
          }
          break;
        }
        case 'edit_function_word': {
          const fw = (lex.function_words as unknown as Row[]).find((f) => f.id === op.entry);
          const field = op.field ?? '';
          if (field !== 'example' || fw === undefined || fw[field] !== op.from || op.to === null) {
            throw new ApplyError(`${op.entry}: expected ${field} "${String(op.from)}"`);
          }
          fw[field] = op.to;
          break;
        }
        case 'spend_bank_root': {
          const spelling = op.entry.replace(/^bank:/, '');
          const bank = (lex as unknown as { reserved_root_bank?: Record<string, unknown> })
            .reserved_root_bank;
          const group = Object.values(bank ?? {}).find(
            (g): g is { count: number; roots: string[] } =>
              typeof g === 'object' &&
              g !== null &&
              Array.isArray((g as { roots?: unknown }).roots) &&
              (g as { roots: string[] }).roots.includes(spelling),
          );
          const owner = byId.get(op.to ?? '');
          if (bank === undefined || group === undefined || op.from !== spelling) {
            throw new ApplyError(`${op.entry}: not in reserved_root_bank`);
          }
          if (owner?.root !== spelling) {
            throw new ApplyError(`${op.entry}: ${String(op.to)} is not spelled ${spelling}`);
          }
          group.roots = group.roots.filter((r) => r !== spelling);
          group.count = group.roots.length;
          if (typeof bank.count === 'number') bank.count -= 1;
          break;
        }
        case 'retire_root':
        case 'merge_entries':
        case 'split_entry':
          throw new ApplyError(`${op.entry}: ${op.op} is not supported by the build`);
      }
      applied.push({ changeset: cs.id, op: op.op, entry: op.entry, to: op.to });
    }
  }

  lex.version = options.version;
  lex.built_utc = options.builtUtc;
  lex.source = options.source;
  lex.rhyme_families = rhymeFamilies(heads.map((h) => h.root));

  // a new edition's rulings and changesets follow the newest of their kind
  const lastKey = (prefix: string, fallback: string): string =>
    Object.keys(baseline)
      .filter((k) => k.startsWith(prefix))
      .pop() ?? fallback;
  const inserts: [string, string, unknown][] = [...rulingsByEdition.entries()].map(
    ([edition, rulings]) => [
      `rulings_${edition.replace('.', '_')}`,
      lastKey('rulings_', 'rulings_0_8_carried'),
      rulings,
    ],
  );
  inserts.push(...sectionInserts);
  inserts.push([
    `changesets_${options.version.replace('.', '_')}`,
    lastKey('changesets_', 'changelog_1_0'),
    changesets.map((c) => ({
      id: c.id,
      edition: c.edition,
      summary: c.summary,
      ops: c.ops.length,
    })),
  ]);
  return { lexicon: withKeys(lex, inserts), applied };
}

export interface BuildAudit {
  passed: boolean;
  findings: string[];
  counts: {
    headwords: number;
    primalRoots: number;
    compounds: number;
    forms: number;
    distinctForms: number;
    functionWords: number;
    correlatives: number;
    lexicalisedDerivations: number;
    rhymeFamilies: number;
  };
}

/** Structural checks on a built lexicon. The sound checker is separate. */
export function auditBuild(
  lex: RawLexicon,
  rules: WordBuilding = STRICT_WORD_BUILDING,
): BuildAudit {
  const findings: string[] = [];
  const heads = lex.headwords as unknown as Headword[];
  const roots = new Set(heads.map((h) => h.root));
  const bases = colourBases(lex);
  const forms: string[] = [];
  for (const h of heads) {
    const want = rawForms(h.root);
    for (const k of RAW_KEYS) {
      if (h.forms[k] !== want[k])
        findings.push(
          `${h.root} ${k}: stored ${String(h.forms[k])}, rule gives ${String(want[k])}`,
        );
      forms.push(h.forms[k] ?? '');
      if (h.glosses[k] === undefined) findings.push(`${h.root}: no ${k} gloss`);
    }
    if (h.type === 'Compound') {
      const parts = h.components ?? [];
      if (parts.join('') + (h.suffix ?? '') !== h.root)
        findings.push(`${h.root}: not its components joined`);
      parts.forEach((c, i) => {
        const colour = i === 0 && rules.colourModifiers && bases.has(c);
        if (!roots.has(c) && !colour) findings.push(`${h.root}: component ${c} is not a headword`);
      });
    }
    if (!Array.isArray(h.english_synonyms) || h.english_synonyms.length === 0) {
      findings.push(`${h.root}: no english_synonyms`);
    }
  }
  const sections: [string, readonly unknown[]][] = [
    ['headwords', lex.headwords],
    ['function_words', lex.function_words],
    ['pronouns', lex.pronouns],
    ['correlatives', lex.correlatives],
    ['time_and_dates', lex.time_and_dates],
    ['colors', lex.colors],
    ['discourse_particles', lex.discourse_particles],
  ];
  const ids = new Set<string>();
  for (const [name, rows] of sections) {
    for (const r of rows as Row[]) {
      if (typeof r.id !== 'string') findings.push(`${name}: a record has no id`);
      else if (ids.has(r.id)) findings.push(`${name}: duplicate id ${r.id}`);
      else ids.add(r.id);
    }
  }
  const distinct = new Set(forms).size;
  if (distinct !== forms.length)
    findings.push(`${String(forms.length - distinct)} forms are not distinct`);
  const primal = heads.filter((h) => h.type === 'Primal').length;
  return {
    passed: findings.length === 0,
    findings,
    counts: {
      headwords: heads.length,
      primalRoots: primal,
      compounds: heads.length - primal,
      forms: forms.length,
      distinctForms: distinct,
      functionWords: lex.function_words.length,
      correlatives: lex.correlatives.length,
      lexicalisedDerivations: Object.keys(lex.morphology.lexicalised_derivations).length,
      rhymeFamilies: lex.rhyme_families.length,
    },
  };
}
